def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-6, atol: float = 1e-12):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)


NAMES = ['Fp1', 'Fp2', 'F7', 'F3', 'Fz', 'F4', 'F8', 'T7', 'C3', 'Cz', 'C4', 'T8',
         'P7', 'P3', 'Pz', 'P4', 'P8', 'O1', 'O2']
for kind in ['standard_1020', 'standard_1005', 'biosemi64', 'biosemi128', 'easycap-M1']:
    m = mne.channels.make_standard_montage(kind)
    pos = m.get_positions()
    check(kind + "_n", [len(m.ch_names)])
    cp = pos['ch_pos']
    check(kind + "_pos", [cp[m.ch_names[0]], cp[m.ch_names[1]], cp[m.ch_names[2]]], 1e-9, 1e-15)
    check(kind + "_fid", [pos['nasion'].__val__(), pos['lpa'].__val__(), pos['rpa'].__val__()], 1e-9, 1e-15)

rng = np.random.RandomState(0)
data = rng.randn(len(NAMES), 50) * 1e-5
info = mne.create_info(NAMES, 100., 'eeg')
raw = mne.io.RawArray(data, info)
raw.set_montage('standard_1020')
check("head_locs", [np.array(raw.info.locs[i][:3]) for i in range(len(NAMES))], 1e-9, 1e-15)
gm = raw.get_montage().__val__().get_positions()
check("get_montage", [gm['ch_pos']['Cz'], gm['ch_pos']['O2'], gm['nasion'].__val__(), gm['lpa'].__val__()], 1e-9, 1e-15)
raw.info['bads'] = ['C3', 'Pz']
r1 = raw.copy().interpolate_bads(origin=(0., 0., 0.04))
check("interp_fixed", r1.get_data(picks=['C3', 'Pz'])[:, :6], 1e-6, 1e-15)
check("interp_bads_after", [len(r1.info['bads'])])
r2 = raw.copy().interpolate_bads(origin='auto')
check("interp_auto", r2.get_data(picks=['C3', 'Pz'])[:, :6], 1e-6, 1e-15)
adj, names = mne.channels.find_ch_adjacency(raw.info, 'eeg')
check("adj", adj.toarray())
dm = mne.channels.make_dig_montage(ch_pos={'A': [0., 0.08, 0.02], 'B': [0.05, 0., 0.06], 'C': [-0.05, 0., 0.06], 'D': [0., -0.08, 0.03]},
                                   nasion=[0., 0.1, 0.], lpa=[-0.08, 0., 0.], rpa=[0.08, 0., 0.], coord_frame='head')
dp = dm.get_positions()['ch_pos']
check("dig", [dp['A'], dp['B'], dp['C'], dp['D']])
raw2 = mne.io.RawArray(data[:5].copy(), mne.create_info(['Fz', 'Cz', 'X1', 'Fp1', 'Pz'], 100., 'eeg'))
eq = mne.channels.equalize_channels([raw.copy(), raw2])
check("eq_n", [len(eq[0].ch_names), len(eq[1].ch_names)])
check("eq_data", eq[1].get_data()[:, :3])
print("done")
